+  await expect(page.getByText('Leave this board?')).toHaveCount(0);
+  await page.evaluate(() => (window as any).__allSpeech[0].onend?.());
+  expect(await page.evaluate(() => (window as any).__spoken)).toEqual(['Cow']);
